import{_ as i,I as n,b as o,d,ah as a,J as r,e as s,i as c,au as l}from"./chunks/framework.7NXsYIIo.js";const k=JSON.parse('{"title":"Node.js tech-check","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"node-js/tech-check/index.md","filePath":"node-js/tech-check/index.md"}'),h={name:"node-js/tech-check/index.md"};function p(u,e,m,g,f,v){const t=n("LearningPath");return d(),o("div",null,[e[0]||(e[0]=a('<h1 id="node-js-tech-check" tabindex="-1">Node.js tech-check <a class="header-anchor" href="#node-js-tech-check" aria-label="Permalink to “Node.js tech-check”">​</a></h1><p>Learn how Node.js works, build applications and practise explaining engineering decisions. Start with Foundations if you are new to Node.js, or choose the level that matches your next goal.</p><p>Work through each level in order. In Foundations, follow each chapter’s first-pass guidance, try its starter examples and build the starter CLI before returning to deeper explanations. Later project increments extend that same application. Use the Completed checkbox below each question or task title to track your progress.</p><p>The <a href="./progressive-projects.html">five progressive projects</a> grow one repository from a command-line program into an operated service.</p><p><img src="'+l+'" alt="Node.js Tech Check levels: Level 1 covers core JavaScript, CLI, npm, modules, asynchronous programming, APIs and basic frameworks; Level 2 covers the event loop, networking, errors, testing, patterns and tools; Level 3 covers architecture, high-load operations, security, databases and cloud; Level 4 covers advanced security, APIs, databases, frameworks and V8 optimization; Level 5 covers tools, queues, WebSockets, WebAssembly and native modules."></p><p><a href="/images/node-js/nodejs-tech-check-levels.png">Open the full-size levels chart</a>.</p><p>Each question has one Level Up career target for its question and answer: L1 Junior, L2 Software Engineer, L3 Senior or L4 Lead. Study depth describes how deeply the lesson teaches the topic. Tech Check stars distinguish explicit chart entries from Related correspondence. The <a href="./requirements.html">source mapping and label guide</a> retains the full career/proficiency matrix without repeating it below every question.</p><h2 id="check-yourself" tabindex="-1">Check yourself <a class="header-anchor" href="#check-yourself" aria-label="Permalink to “Check yourself”">​</a></h2><p><a href="./check-yourself.html">Start an interactive assessment</a> with a repository prompt or a portable version to share. Choose Tech Check or Level Up, full or half length, and broad or focused topic coverage.</p><h2 id="node-js-foundations" tabindex="-1">Node.js Foundations <a class="header-anchor" href="#node-js-foundations" aria-label="Permalink to “Node.js Foundations”">​</a></h2><p>Understand the runtime and build command-line programs with modules, asynchronous code and core APIs.</p><p>Start here if you know variables, functions, arrays and basic JavaScript control flow. Core JavaScript below reviews references, <code>this</code> and closures; it is not a complete introduction to the language.</p><p><strong>Your first goal is a small working CLI.</strong> Read each chapter’s first-pass guidance rather than treating every advanced question as a prerequisite. The Core answer gives the main idea; try the short example, change one input and explain the result. Expand the deeper explanation when you are ready for more detail.</p>',13)),r(t,{"path-id":"foundations"}),e[1]||(e[1]=a('<p>Finish the <a href="./progressive-projects.html#starter-cli-milestone">starter CLI milestone</a> before attempting event-based storage, streaming reports or shutdown drills. These later increments remain part of the full Foundations project, but are separate learning steps.</p><h2 id="building-node-js-applications" tabindex="-1">Building Node.js Applications <a class="header-anchor" href="#building-node-js-applications" aria-label="Permalink to “Building Node.js Applications”">​</a></h2><p>Build and test HTTP applications, handle failures and choose useful application patterns.</p><p><strong>Begin with the finished Project 1 release</strong>, including its <a href="./progressive-projects.html#project-1-handoff-contract">handoff contract</a>. Start a small Express app, then run its NestJS counterpart. Add middleware, errors and a unit/HTTP test before diving into network protocols or process supervision.</p><p>NestJS remains part of this level: learn controllers, providers and modules first; add guards, pipes, filters and interceptors alongside the matching application concerns. Follow each chapter&#39;s first-pass guide rather than treating every complete lab as an opening exercise.</p>',5)),r(t,{"path-id":"applications"}),e[2]||(e[2]=a('<p>Use the <a href="./progressive-projects.html#first-http-milestone">first HTTP milestone</a> for an early checkpoint. Then complete the remaining Project 2 increments and release checks before starting Services.</p><h2 id="designing-node-js-services" tabindex="-1">Designing Node.js Services <a class="header-anchor" href="#designing-node-js-services" aria-label="Permalink to “Designing Node.js Services”">​</a></h2><p>Design service boundaries, persistence, access control and deployment.</p><p><strong>Continue from the full Section 2 project.</strong> Keep its HTTP/CLI contracts, tests and NestJS companion. Work through architecture → PostgreSQL/SQL/ORM → identity → worker reports → containers/deployment. The chapter guides distinguish the required service implementation from advanced distributed-system and Section 4 extensions.</p><p>Complete the <a href="./progressive-projects.html#project-3-checkpoint-levels">Project 3 local/design checkpoint</a> first. Cloud execution has a separate checkpoint; a local pass is not a claim that AWS deployment or recovery was tested.</p>',5)),r(t,{"path-id":"services"}),e[3]||(e[3]=a('<h3 id="section-3-vocabulary" tabindex="-1">Terms used in Section 3 <a class="header-anchor" href="#section-3-vocabulary" aria-label="Permalink to “Terms used in Section 3”">​</a></h3><p>The technical terms below are useful when reading documentation and discussing services. Learn the term together with its meaning; you do not need more advanced English to understand the underlying idea.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning in these lessons</th></tr></thead><tbody><tr><td>Principal</td><td>Verified information about the caller, such as user ID and permissions</td></tr><tr><td>Scope</td><td>The set of data or actions an operation is allowed to access</td></tr><tr><td>Invariant</td><td>A business rule that must remain true, even when operations overlap</td></tr><tr><td>Payload</td><td>The data carried in a request or message</td></tr><tr><td>Serialization</td><td>Converting values into a format that can be stored or sent</td></tr><tr><td>Admission</td><td>Deciding whether to accept new work or reject it because capacity is full</td></tr><tr><td>Correlation</td><td>Using an ID to match a reply or log record with its request</td></tr><tr><td>Settlement</td><td>A promise resolving or rejecting; this does not always mean the underlying work stopped</td></tr><tr><td>Terminal state</td><td>A final state such as completed, failed or cancelled</td></tr><tr><td>Drain</td><td>Let already accepted work finish before closing resources</td></tr><tr><td>Idempotency</td><td>Repeating the same operation does not repeat its intended business effect</td></tr><tr><td>Reconciliation</td><td>Checking what actually happened when an operation’s outcome is uncertain</td></tr><tr><td>Retention</td><td>How long data, files or records are kept</td></tr><tr><td>Artifact</td><td>A produced file, package or image, such as a report or release image</td></tr><tr><td>Rollout / rollback</td><td>Introducing a release / returning to a previous compatible release</td></tr><tr><td>Test fixture</td><td>A controlled test setup and its data</td></tr></tbody></table><h2 id="hardening-and-optimizing-node-js-services" tabindex="-1">Hardening and Optimizing Node.js Services <a class="header-anchor" href="#hardening-and-optimizing-node-js-services" aria-label="Permalink to “Hardening and Optimizing Node.js Services”">​</a></h2><p>Strengthen security and use measurements to improve performance and data access.</p>',5)),r(t,{"path-id":"hardening"}),e[4]||(e[4]=s("h2",{id:"specialized-systems",tabindex:"-1"},[c("Specialized Node.js Systems "),s("a",{class:"header-anchor",href:"#specialized-systems","aria-label":"Permalink to “Specialized Node.js Systems”"},"​")],-1)),e[5]||(e[5]=s("p",null,"Operate message-driven and real-time services with logs, monitoring and specialist integrations.",-1)),r(t,{"path-id":"specialized"}),e[6]||(e[6]=a('<h2 id="node-js-tech-check-levels-chart" tabindex="-1">Node.js Tech Check levels chart <a class="header-anchor" href="#node-js-tech-check-levels-chart" aria-label="Permalink to “Node.js Tech Check levels chart”">​</a></h2><p>The chart summarizes the five levels and their topic groups, from JavaScript and Node.js foundations to specialized systems.</p><ul><li><a href="/images/node-js/nodejs-tech-check-levels.png">View the full-size levels chart</a>.</li><li><a href="./requirements.html#source-matrix">Open the sortable requirements matrix</a>: compare all 193 requirements by topic, Level Up proficiency and Tech Check level.</li></ul><h2 id="practice-and-references" tabindex="-1">Practice and references <a class="header-anchor" href="#practice-and-references" aria-label="Permalink to “Practice and references”">​</a></h2><ul><li><a href="./../">Node.js runtime course</a>: longer explanations and guided lessons.</li><li><a href="./../../practice/node-js/">Node.js exercises</a>: independent implementation tasks.</li><li><a href="./js-tech-check.html">JavaScript technical questions</a>: language concepts to review alongside Node.js.</li><li><a href="./react-tech-check.html">React technical questions</a>: frontend concepts for your application&#39;s interface.</li><li><a href="./requirements.html#source-matrix">Sortable requirements table</a>: compare all 193 requirements by topic, Level Up proficiency and Tech Check level.</li></ul>',5))])}const T=i(h,[["render",p]]);export{k as __pageData,T as default};
